mapper.select:
-- ===== STUDENT 证书：按 certificate 聚合 ===== SELECT c.id, c.cert_type, c.cert_number, col.college_name, ce.event_name, ce.level, cs.session_name, sg.group_name, cc.category_name, c.cert_title, c.award_level, c.issue_date, c.resource_key, c.status, c.remark, c.reject_reason, -- 学生聚合 (SELECT COALESCE(ARRAY_AGG(u.real_name ORDER BY u.real_name), ARRAY[]::text[]) FROM certificate_recipient cr2 JOIN sys_user u ON cr2.user_id = u.id WHERE cr2.certificate_id = c.id) as student_names, (SELECT COALESCE(ARRAY_AGG(u.student_id ORDER BY u.student_id), ARRAY[]::text[]) FROM certificate_recipient cr2 JOIN sys_user u ON cr2.user_id = u.id WHERE cr2.certificate_id = c.id) as student_ids, -- 教师聚合（从certificate_recipient.instructor_id获取，去重） (SELECT COALESCE(ARRAY_AGG(DISTINCT u.real_name ORDER BY u.real_name), ARRAY[]::text[]) FROM certificate_recipient cr2 JOIN sys_user u ON cr2.instructor_id = u.id WHERE cr2.certificate_id = c.id) as teacher_names, (SELECT COALESCE(ARRAY_AGG(DISTINCT u.teacher_id ORDER BY u.teacher_id), ARRAY[]::text[]) FROM certificate_recipient cr2 JOIN sys_user u ON cr2.instructor_id = u.id WHERE cr2.certificate_id = c.id) as teacher_ids FROM certificate c LEFT JOIN college col ON c.owner_college_id = col.id LEFT JOIN competition_event ce ON c.event_id = ce.id LEFT JOIN competition_session cs ON c.session_id = cs.id LEFT JOIN subject_group sg ON c.group_id = sg.id LEFT JOIN competition_category cc ON c.category_id = cc.id WHERE c.cert_type = 'STUDENT' AND c.status = 'PENDING_REVIEW'
AND c.owner_college_id = #{collegeId}
UNION ALL
-- ===== INSTRUCTOR 证书：不聚合，每个教师单独一行 ===== SELECT c.id, c.cert_type, c.cert_number, col.college_name, ce.event_name, ce.level, cs.session_name, sg.group_name, cc.category_name, c.cert_title, c.award_level, c.issue_date, c.resource_key, c.status, c.remark, c.reject_reason, -- 学生：教师证书无获得者 ARRAY[]::text[] as student_names, ARRAY[]::text[] as student_ids, -- 教师：当前记录关联的教师本人 ARRAY[holder.real_name]::text[] as teacher_names, ARRAY[holder.teacher_id]::text[] as teacher_ids FROM certificate_instructor ci INNER JOIN certificate c ON ci.certificate_id = c.id LEFT JOIN college col ON c.owner_college_id = col.id LEFT JOIN competition_event ce ON c.event_id = ce.id LEFT JOIN competition_session cs ON c.session_id = cs.id LEFT JOIN subject_group sg ON c.group_id = sg.id LEFT JOIN competition_category cc ON c.category_id = cc.id LEFT JOIN sys_user holder ON ci.user_id = holder.id WHERE c.cert_type = 'INSTRUCTOR' AND c.status = 'PENDING_REVIEW'
AND c.owner_college_id = #{collegeId}
ORDER BY created_at DESC, id
